import{_ as l,c as e,o as a,a5 as i}from"./chunks/framework.BLFC1wTn.js";const k=JSON.parse('{"title":"Webpack","description":"","frontmatter":{},"headers":[],"relativePath":"pages/interview/webpack/index.md","filePath":"pages/interview/webpack/index.md","lastUpdated":null}'),o={name:"pages/interview/webpack/index.md"},r=i('<h1 id="webpack" tabindex="-1">Webpack <a class="header-anchor" href="#webpack" aria-label="Permalink to &quot;Webpack&quot;">​</a></h1><h2 id="webpack工作流程" tabindex="-1">Webpack工作流程 <a class="header-anchor" href="#webpack工作流程" aria-label="Permalink to &quot;Webpack工作流程&quot;">​</a></h2><ol><li>初始化参数，从配置文件读取合并参数，得到最终参数</li><li>开始编译，用上一步得到的参数初始化Complier对象，加载所有配置的插件，开始执行编译</li><li>确定入口，根据entry找到入口文件</li><li>编译模板，从入口文件出发，调用所有配置的loadder对模块进行翻译，再找到该模块依赖的模块，递归本步骤</li><li>完成模块编译，经过第三步完成模块编译并获得他们之间的依赖关系</li><li>输出资源，根据入口和模块之间额依赖关系，组装成一个个包含多个模块的Chunk，再把每个Chunk转换成一个单独的文件加入到输出列表，这步是修改输出内容的最后机会</li><li>输出完成，确定后输出内容后，根据配置文件确定输出的路径和文件名，把文件内容写入到文件系统</li></ol><h2 id="什么是loader-plugin" tabindex="-1">什么是Loader，Plugin <a class="header-anchor" href="#什么是loader-plugin" aria-label="Permalink to &quot;什么是Loader，Plugin&quot;">​</a></h2><p>loader：让webpack拥有加载和解析其他非JS文件的能力，webpack只能支持JS文件解析，loader在module.rules中配置，作为模板的解析规则，类型为数组，每一项都是一个Object，内部包含了test、loader、options等属性 plugin：plugin可以扩展webpack的功能，在webpack运行的生命周期中会广播许多事件，plugin可以监听这些事件，在合适的时机通过webpack提供的API改变结果，plugins中单独配置，类型为数组，每一项都是一个Plugin的实例</p><h2 id="常见的loader" tabindex="-1">常见的Loader <a class="header-anchor" href="#常见的loader" aria-label="Permalink to &quot;常见的Loader&quot;">​</a></h2><ol><li>raw-loader，加载文件的原始内容(utf-8)</li><li>file-loader，处理文件，将文件复制到输出目录，并返回它们的URL</li><li>url-loader，与file-loader类似，区别是可以设置一个阈值，大于阈值会交给file-loader，小于阈值返回base64</li><li>source-map-loader，加载额外的sourceMap文件，方便调式</li><li>svg-inline-loader，将压缩后的svg内容注入代码</li><li>image-loader，加载并压缩图片</li><li>json-loader，加载JSON文件</li><li>handlebars-loader，将Handlebars模板编译成函数并返回</li><li>babel-loader，把ES6转换成ES5</li><li>ts-loader，ts转为js</li><li>awesome-typescript-loader，ts转为js，性能比ts-loader好</li><li>sass-loader，将sass转为css</li><li>css-loader，加载css，支持模块化、压缩、导入</li><li>style-loader，把css代码注入到js中</li><li>postcss-loader，扩展css语法，做兼容</li><li>eslint-loader，eslint检查js</li><li>tslint-loader，tslint检查TS</li></ol><h2 id="常见plugin" tabindex="-1">常见Plugin <a class="header-anchor" href="#常见plugin" aria-label="Permalink to &quot;常见Plugin&quot;">​</a></h2><ol><li>define-plugin，定义环境变量</li><li>ignore-plugin，忽略部分文件</li><li>html-webpack-plugin，简化HTML文件创建(依赖于html-loader)</li><li>web-webpack-plugin，可方便地为单页应用输出HTML</li><li>uglifyjs-webpack-plugin，压缩文件</li><li>terser-webpack-plugin，压缩文件</li><li>webpack-paralled-uglify-plugin，多进程执行代码压缩，提高构建速度</li><li>mini-css-extract-plugin，分类样式文件，提取css为单独的文件，支持按需加载</li><li>serviceworker-webpack-plugin：为网页应用增加离线缓存功能</li><li>clean-wenpack-plugin，目录清理</li><li>ModuleConcatenationplugin，开启Scope Hoisting</li><li>speed-measure-webpack-plugin，可以看到每个loader和plugin的执行耗时、打包耗时</li><li>webpack-bundle-analyzer，可视化webpack输出文件的体积</li></ol><h2 id="webpack热更新hmr" tabindex="-1">Webpack热更新HMR <a class="header-anchor" href="#webpack热更新hmr" aria-label="Permalink to &quot;Webpack热更新HMR&quot;">​</a></h2><p>HMR全称Hot Module Replacement，是Webpack提供的一种在不刷新浏览器的情况下更新模块的功能。 HMR的核心是客户端从服务器拉取更新后的文件，准确的说是chunk diff，实际上WDS(Webpack Dev Server)与浏览器之间维护了一个WebSocket，当文件资源发生变化时，WDS会向浏览器推送更新，并带上构建时的hash，让客户端与上一次的资源进行比对。客户端对比出差异后会向WDS发起AJAX请求来获取更新内容</p><h2 id="代码分割的意义" tabindex="-1">代码分割的意义 <a class="header-anchor" href="#代码分割的意义" aria-label="Permalink to &quot;代码分割的意义&quot;">​</a></h2><p>代码分割的本质是在源代码直接上线和打包成唯一脚本的main.bundle.js两种极端方案之间的中间状态，使用可接受的服务器压力来换取更好的用户体验。</p><ol><li>源代码直接上线，过程可控，http请求多，性能开销大</li><li>打包成唯一脚本，服务器压力小，但是页面空白期长，用户体验不好</li></ol><h2 id="webpack打包速度优化" tabindex="-1">Webpack打包速度优化 <a class="header-anchor" href="#webpack打包速度优化" aria-label="Permalink to &quot;Webpack打包速度优化&quot;">​</a></h2><ol><li>优化loader，对loader来说，影响打包效率的主要是Babel，Babel会把代码转换为字符换生成AST，然后对AST继续转换最后生成新代码，项目越大，转换代码越慢</li><li>HappyPack，受限于Node的单线程，Webpack也是单线程，而HappyPack可以将Loader的同步执行转为并行，提高打包速度</li><li>DllPugin，可以将特定的类库提前打包然后引入，可以极大地减少打包类库的次数，只有当类库更新版本时才重新打包，也实现了将公共代码抽离成单独文件的优化</li><li>代码压缩，在Webpack3中，一般使用UglifyJs压缩代码，但是这个是单线程运行的，使用webpack-parallel-uglify-plugin可以多进程运行UglifyJs，在webpack4中，只需要设置mode为production即可自动压缩代码</li></ol><h2 id="webpack减少打包体积" tabindex="-1">Webpack减少打包体积 <a class="header-anchor" href="#webpack减少打包体积" aria-label="Permalink to &quot;Webpack减少打包体积&quot;">​</a></h2><ol><li>按需加载，将每个路由页面单独打包为一个文件，只有当前页面需要时才加载，可以有效减少初始加载时间，也可以对loadash这中类库使用</li><li>Scope Hoisting，可以分析出模块间的依赖关系，尽可能的把打包出来的模块合并到一个函数中去</li><li>Tree-Shaking，Tree-Shaking是Webpack4中新增的特性，可以分析出模块间的依赖关系，只保留用到的模块，可以有效减少打包体积</li></ol><h2 id="webpack优化前端性能" tabindex="-1">Webpack优化前端性能 <a class="header-anchor" href="#webpack优化前端性能" aria-label="Permalink to &quot;Webpack优化前端性能&quot;">​</a></h2><ol><li>压缩代码，压缩JS、CSS文件等</li><li>CDN加速，在构建过程中，将引用的静态资源路径修改为CDN上对应的路径，可以利用webpack对于output参数和各loader的publicPath参数来修改资源路径</li><li>Tree-Shaking</li><li>Code-Splitting，将代码拆分成多个文件，按需加载，可以有效减少初始加载时间，提高用户体验</li><li>SplitChunksPlugin，可以将公共代码抽离成单独文件，减少请求数，提高加载速度</li></ol><h2 id="webpack构建速度优化" tabindex="-1">Webpack构建速度优化 <a class="header-anchor" href="#webpack构建速度优化" aria-label="Permalink to &quot;Webpack构建速度优化&quot;">​</a></h2><ol><li>多入口的情况下，使用CommonsChunkPlugin来提取公共代码</li><li>通过exterals参数，将一些公共库提前打包，减少请求数</li><li>利用DllPlugin和DllReferencePlugin预编译资源模块，通过DllPlugin来对那些引用但不会修改的npm包进行预编译，再通过DllReferencePlugin来引用预编译好的资源，可以极大地减少打包时间</li><li>HappyPack，可以将Loader的同步执行转为并行，提高打包速度</li><li>webpack-parallel-uglify-plugin，多进程运行UglifyJs，提高压缩速度</li><li>Tree-Shaking和Scope Hoisting，可以剔除多余代码</li></ol><h2 id="webpack长缓存" tabindex="-1">Webpack长缓存 <a class="header-anchor" href="#webpack长缓存" aria-label="Permalink to &quot;Webpack长缓存&quot;">​</a></h2><p>用访问浏览器页面时，为了加快加载速度，会对用户访问的静态资源进行存储，但每一次代码升级或更新，都需要浏览器下载新的代码，最方便的方式时引入新的文件名称，只下载新的代码块，不会加载旧的代码块<br> 在Webpack中，可以通过output给输出文件定义指定chunkhash，并且分离经常更新的代码，通过NameModulesPlugin或者HashedModuleIdsPlugin使再次打包的文件名不变</p><h2 id="weback实现按需加载" tabindex="-1">Weback实现按需加载 <a class="header-anchor" href="#weback实现按需加载" aria-label="Permalink to &quot;Weback实现按需加载&quot;">​</a></h2><p>import(&quot;module&quot;)</p><h2 id="神奇注释" tabindex="-1">神奇注释 <a class="header-anchor" href="#神奇注释" aria-label="Permalink to &quot;神奇注释&quot;">​</a></h2><p>在import里面可以添加一些注释，如定义该chunk的名称、要过滤的文件，引入指定的文件等，这类带有特殊功能的注释被称为神奇注释</p><h2 id="npm-run-dev的时候webpack做了什么" tabindex="-1">npm run dev的时候webpack做了什么 <a class="header-anchor" href="#npm-run-dev的时候webpack做了什么" aria-label="Permalink to &quot;npm run dev的时候webpack做了什么&quot;">​</a></h2><ol><li>检查node和npm版本，引入相关插件和配置</li><li>webpack对源码进行编译打包并返回complier对象</li><li>创建express服务器</li><li>配置开发中间件(webpack-dev-middleware)和热重载中间件(webpack-hot-middleware)</li><li>挂载代理服务和中间件</li><li>配置静态资源</li><li>启动服务器监听特定端口</li><li>打开浏览器</li></ol>',30),n=[r];function p(c,t,d,s,b,u){return a(),e("div",null,n)}const g=l(o,[["render",p]]);export{k as __pageData,g as default};
